import{_ as a,o,c as i,a2 as l}from"./chunks/framework.CHeM0PsO.js";const t="/images/bot-dm-start.webp",c="/images/bot-dm-follow.webp",d="/images/bot-dm-inbox.webp",r="/images/migration-export.webp",s="/images/migration-download.webp",f=JSON.parse('{"title":"从旧版 Aliya Bot 迁移","description":"","frontmatter":{},"headers":[],"relativePath":"guide/migration.md","filePath":"guide/migration.md","lastUpdated":1789295632000}'),n={name:"guide/migration.md"};function p(m,e,h,u,_,g){return o(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="从旧版-aliya-bot-迁移" tabindex="-1">从旧版 Aliya Bot 迁移 <a class="header-anchor" href="#从旧版-aliya-bot-迁移" aria-label="Permalink to &quot;从旧版 Aliya Bot 迁移&quot;">​</a></h1><p>本章面向仍在使用旧版 Aliya bot 的用户。推荐切换到新版 Aliya 智能体，体验更好、功能更全，并且可以<a href="#数据迁移到智能体">保留原有聊天记忆</a>。</p><h2 id="发起私信" tabindex="-1">发起私信 <a class="header-anchor" href="#发起私信" aria-label="Permalink to &quot;发起私信&quot;">​</a></h2><p>通过 Misskey，您可以轻松地与 Aliya 建立联系。</p><p>如果您需要向此前未曾与之聊天过的用户发起私信，请访问 Misskey 主页，依次点击 <strong>发现 – 用户 – 用户头像</strong>。</p><p><img src="'+t+'" alt="发现用户并发起私信"></p><p>进入个人资料后，由于用户隐私政策，需要关注用户后才能发起私信。因此，请先关注用户，然后点击右上角三个点 – 私信。</p><p><img src="'+c+'" alt="关注 Aliya（谢谢喵）"></p><p>如果需要再次进入聊天，只需在左侧菜单栏找到 <strong>消息</strong> 并点击即可。</p><p><img src="'+d+'" alt="进入私聊"></p><h2 id="常用指令" tabindex="-1">常用指令 <a class="header-anchor" href="#常用指令" aria-label="Permalink to &quot;常用指令&quot;">​</a></h2><h3 id="会话相关" tabindex="-1">会话相关 <a class="header-anchor" href="#会话相关" aria-label="Permalink to &quot;会话相关&quot;">​</a></h3><ul><li><code>/ls</code>（无参数）：查看当前会话的对话列表。</li><li><code>/new</code>（无参数）：创建一个新的对话，原对话记录将保留。</li><li><code>/rename 文字</code>：重命名当前对话。</li><li><code>/switch 序号</code>：在多个对话历史之间进行切换。 <ul><li>注：序号为对话名称前面的数字。</li></ul></li><li><code>/del</code>（无参数）：将当前对话从对话记录中删除。 <ul><li>警告：该操作不可逆！</li></ul></li></ul><h3 id="功能相关" tabindex="-1">功能相关 <a class="header-anchor" href="#功能相关" aria-label="Permalink to &quot;功能相关&quot;">​</a></h3><ul><li><code>/ch 数量</code>：遗忘最近指定数量的对话，若未指定则默认为 1。</li><li><code>/draw</code>（根命令）：用于查询、更改画图工具状态，详情请发送 <code>/draw</code>。</li><li><code>/hg</code>（无参数）：查询当前 Aliya 对您的好感度。</li><li><code>/model</code>（根命令）：查询、更改当前对话模型状态（当前使用的模型、额度等），详情请发送 <code>/model</code>。</li><li><code>/rc</code>（根命令）：查询日程提醒，详情请发送 <code>/rc</code>。</li><li><code>/time</code>（根命令）：时间系统，用于查询、修改您和 Aliya 的时间线，详情请发送 <code>/time</code>。</li><li><code>/xf</code>（无参数）：修复当前对话。</li><li><code>/yh</code>（无参数）：若对话质量较低，请尝试发送此命令进行优化，再次发送可关闭优化。 <ul><li>注：开启优化可能会增加您的 tokens 或额度用量。</li></ul></li></ul><h2 id="数据迁移到智能体" tabindex="-1">数据迁移到智能体 <a class="header-anchor" href="#数据迁移到智能体" aria-label="Permalink to &quot;数据迁移到智能体&quot;">​</a></h2><p><img src="'+r+'" alt="导出文件"></p><p>① 如图，使用 <code>/export_context</code> 指令，下载聊天记录文件。</p><p><img src="'+s+'" alt="下载文件"></p><p>② 在智能体功能中找到 Aliya 角色，点击开始聊天，创建新的会话。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>请务必创建新会话，避免聊天记忆被覆盖。</p></div><p>③ 完成基础配置，详见<a href="/guide/agent/quick-start">智能体快速开始</a>。</p>',22)])])}const y=a(n,[["render",p]]);export{f as __pageData,y as default};
